import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"離","description":"周易正义 - 離","frontmatter":{"title":"離","description":"周易正义 - 離"},"headers":[],"relativePath":"zh/classics/zhengyi/030.md","filePath":"zh/classics/zhengyi/030.md"}'),l={name:"zh/classics/zhengyi/030.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>离为火</p></blockquote><blockquote><p>卦辞：利贞，亨。畜牝牛吉。</p></blockquote><blockquote><p>彖曰：离，丽也。日月丽乎天，百谷草木丽乎土。重明以丽乎正，乃化成天下。柔丽乎中正，故亨，是以畜牝牛吉也。</p></blockquote><h1 id="離" tabindex="-1">離 <a class="header-anchor" href="#離" aria-label="Permalink to “離”">​</a></h1><p>王弼：离之为卦，以柔为正，故必贞而后乃亨，故曰“利贞亨”也。</p><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>“离利贞亨”。○正义曰：离，丽也。丽谓附著也。言万物各得其所附著处，故谓之“离”也。“利贞亨”者，离卦之体，阴柔为主，柔则近於不正，不正则不亨通，故利在行正，乃得亨通。以此故“亨”在“利贞”之下，故云“利贞亨”。○注“离之为卦”至“利贞亨也”。○正义曰：“离之为卦，以柔为正”者，二与五俱是阴爻，处於上下两卦之中，是以柔为正。</p><h3 id="畜牝牛-吉。-​" tabindex="-1">畜牝牛，吉。 ​ <a class="header-anchor" href="#畜牝牛-吉。-​" aria-label="Permalink to “畜牝牛，吉。 ​”">​</a></h3><p>王弼：柔处于内而履正中，牝之善也。外强而内顺，牛之善也。离之为体，以柔顺为主者也。故不可以畜刚猛之物，而“吉”於“畜牝牛”也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>“畜牝牛吉”。正义曰：柔处於内而履正中，是牝之善者，外强内顺，是牛之善者也。离之为体，以柔顺为主，故畜养牝牛，乃得其吉。若畜养刚健，则不可也。此云“畜牝牛”，假象以明人事也。言离之为德，须内顺外强，而行此德则得吉也。若内刚外顺，则反离之道也。○注“柔处于内”至“畜牝牛也”。○正义曰：“柔处於内而履正中牝之善也”者，若柔不处於内，似妇人而预外事；若柔而不履正中，则邪僻之行，皆非牝之善也。若柔能处中，行能履正，是为“牝之善”也。云“外强而内顺牛之善”者，若内外俱强，则失於猛害；若外内俱顺，则失於劣弱。唯外强内顺，於用为善，故云“外强内顺牛之善也”。“离之为体，以柔顺为主，故不可以畜刚猛之物”者，既以柔顺为主，若畜刚猛之物，则反其德，故不可畜刚猛而“畜牝牛”也。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="离-丽也。-​" tabindex="-1">离，丽也。 ​ <a class="header-anchor" href="#离-丽也。-​" aria-label="Permalink to “离，丽也。 ​”">​</a></h3><p>王弼：丽犹著也。各得所著之宜。</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：释离卦之名。丽谓附著也。以阴柔之质，附著中正之位，得所著之宜，故云“丽”也。</p><h3 id="日月丽乎天-百穀草木丽乎土。重明以丽乎正-乃化成天下。柔丽乎中正-故亨。是以-畜牝牛-吉-也。-​" tabindex="-1">日月丽乎天，百穀草木丽乎土。重明以丽乎正，乃化成天下。柔丽乎中正，故亨。是以“畜牝牛，吉”也。 ​ <a class="header-anchor" href="#日月丽乎天-百穀草木丽乎土。重明以丽乎正-乃化成天下。柔丽乎中正-故亨。是以-畜牝牛-吉-也。-​" aria-label="Permalink to “日月丽乎天，百穀草木丽乎土。重明以丽乎正，乃化成天下。柔丽乎中正，故亨。是以“畜牝牛，吉”也。 ​”">​</a></h3><p>王弼：柔著于中正，乃得通也。柔通之吉，极於“畜牝牛”，不能及刚猛也。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>“日月丽乎天”至“是以畜牝牛吉也”。○正义曰：“日月丽乎天，百穀草木丽乎土”者，此广明附著之义。以柔附著中正，是附得宜，故广言所附得宜之事也。“重明以丽乎正，乃化成天下”者，此以卦象，说离之功德也，并明“利贞”之义也。“重明”，谓上下俱离。“丽乎正”者，谓两阴在内，既有重明之德，又附於正道，所以“化成天下”也。然阴居二位，可谓为正。若阴居五位，非其正位，而云“重明丽乎正”者，以五处於中正，又居尊位，虽非阴阳之正，乃是事理之正，故总云“丽於正”也。“柔丽乎中正，故亨。是以牝牛吉”者，释《经》“亨”义也，又总释“畜牝牛吉”也。“柔丽於中正”，谓六五、六二之柔，皆丽於中，中则不偏，故云“中正”。以中正为德，故万事亨。以中正得通，故畜养牝牛而得吉也。以牝牛有中正故也。案诸卦之《彖》，释卦名之下，乃释卦下之义，於后乃叹而美之。此《彖》既释卦名，即广叹为卦之美，乃释卦下之义。与诸卦不例者，此乃夫子随义则言，因文之便也。比既释“离”名丽，因广说日月草木所丽之事，然后却明卦下之义，更无义例。</p><h2 id="《象》曰-明两作-离。大人以继明照于四方。-​" tabindex="-1">《象》曰：明两作，离。大人以继明照于四方。 ​ <a class="header-anchor" href="#《象》曰-明两作-离。大人以继明照于四方。-​" aria-label="Permalink to “《象》曰：明两作，离。大人以继明照于四方。 ​”">​</a></h2><p>王弼：“继”谓不绝也，明照相继，不绝旷也。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“明两作离”者，离为日，日为明。今有上下二体，故云“明两作，离”也。案：八纯之卦，论象不同，各因卦体事义，随文而发。乾、坤不论上下之体，直总云“天行健”、“地势坤”，以天地之大，故总称上下二体也。雷是连续之至，水为流注不已，义皆取连续相因，故震云“洊雷”，坎云“洊至”也。风是摇动相随之物，故云“随风巽”也。山泽各自为体，非相入之物，故云“兼山艮”，“丽泽兑”，是两物各行也。今明之为体，前后各照，故云“明两作，离”，是积聚两明，乃作於离。若一明暂绝，其离未久，必取两明前后相续，乃得作离卦之美，故云“大人以继明照於四方”，是继续其明，乃照於四方。若明不继续，则不得久为照临，所以特云“明两作，离”，取不绝之义也。</p><h2 id="初九-履错然-敬之-无咎。-​" tabindex="-1">初九：履错然，敬之，无咎。 ​ <a class="header-anchor" href="#初九-履错然-敬之-无咎。-​" aria-label="Permalink to “初九：履错然，敬之，无咎。 ​”">​</a></h2><p>王弼：“错然”者，警慎之貌也。处离之始，将进而盛，未在既济，故宜慎其所履，以敬为务，辟其咎也。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>“初九，履错然，敬之无咎”。○正义曰：“履错然”者，身处离初，将欲前进，其道未济，故其所履践，恒错然敬慎不敢自宁，故云“履错然敬之无咎”。若能如此恭敬，则得避其祸而“无咎”，故《象》云：“履错之敬，以避咎也”。○注“错然者警慎之貌也”至“辟其咎也”。○正义曰：“错然者警慎之貌”者，是警惧之状，其心未宁故“错然”也。言“处离之始，将进而盛，未在既济”者，“将进而盛”，谓将欲前进而向盛也。若位在於三，则得“既济”。今位在於初，是未在“既济”。谓功业未大，故宜慎其所履，恒须错然避咎也。</p><h3 id="《象》曰-履错-之敬-以辟咎也。-​" tabindex="-1">《象》曰：“履错”之敬，以辟咎也。 ​ <a class="header-anchor" href="#《象》曰-履错-之敬-以辟咎也。-​" aria-label="Permalink to “《象》曰：“履错”之敬，以辟咎也。 ​”">​</a></h3><h2 id="六二-黄离-元吉。-​" tabindex="-1">六二：黄离，元吉。 ​ <a class="header-anchor" href="#六二-黄离-元吉。-​" aria-label="Permalink to “六二：黄离，元吉。 ​”">​</a></h2><p>王弼：居中得位，以柔处柔，履文明之盛而得其中，故曰“黄离元吉”也。</p><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：黄者中色，“离”者文明。居中得位而处於文明，故“元吉”也。故《象》云“得中道”，以其得中央黄色之道也。</p><h3 id="《象》曰-黄离元吉-得中道也。-​" tabindex="-1">《象》曰：“黄离元吉”，得中道也。 ​ <a class="header-anchor" href="#《象》曰-黄离元吉-得中道也。-​" aria-label="Permalink to “《象》曰：“黄离元吉”，得中道也。 ​”">​</a></h3><h2 id="九三-日昃之离-不鼓缶而歌-则大耋之嗟-凶。-​" tabindex="-1">九三：日昃之离，不鼓缶而歌，则大耋之嗟，凶。 ​ <a class="header-anchor" href="#九三-日昃之离-不鼓缶而歌-则大耋之嗟-凶。-​" aria-label="Permalink to “九三：日昃之离，不鼓缶而歌，则大耋之嗟，凶。 ​”">​</a></h2><p>王弼：嗟，忧叹之辞也。处下离之终，明在将没，故曰“日昃之离”也。明在将终，若不委之於人，养志无为，则至於耋老有嗟，凶矣，故曰“不鼓缶而歌，则大耋之嗟凶”也。</p><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“日昃之离”者，处下离之终，其明将没，故云“日昃之离”也。“不鼓缶而歌，大耋之嗟凶”者，时既老耄，当须委事任人，自取逸乐。若不委之於人，则是不鼓击其缶而为歌，则至於大耋老耄而咨嗟，何可久长？所以凶也。故《象》云：“日昃之离，何可久也？”</p><h3 id="《象》曰-日昃之离-何可久也-​" tabindex="-1">《象》曰：“日昃之离”，何可久也？ ​ <a class="header-anchor" href="#《象》曰-日昃之离-何可久也-​" aria-label="Permalink to “《象》曰：“日昃之离”，何可久也？ ​”">​</a></h3><h2 id="九四-突如其来如-焚如-死如-弃如。-​" tabindex="-1">九四：突如其来如，焚如，死如，弃如。 ​ <a class="header-anchor" href="#九四-突如其来如-焚如-死如-弃如。-​" aria-label="Permalink to “九四：突如其来如，焚如，死如，弃如。 ​”">​</a></h2><p>王弼：处於明道始变之际，昏而始晓，没而始出，故曰“突如其来如”。其明始进，其炎始盛，故曰“焚如”。逼近至尊，履非其位，欲进其盛，以炎其上，命必不终，故曰“死如”。违“离之义，无应无承，无所不容，故曰“弃如”也。</p><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>“九四，突如其来如，焚如，死如，弃如”。○正义曰：“突如其来如”者，四处始变之际，三为始昏，四为始晓。三为已没，四为始出，突然而至，忽然而来，故曰“突如其来如”也。“焚如”者，逼近至尊，履非其位，欲进其盛，以焚炎其上，故云“焚如”也。死如者，既焚其上，命必不全，故云“死如”也。“弃如”者，违於离道，无应无承，众所不容，故云“弃如”。是以《象》云：“无所容也。”</p><h3 id="《象》曰-突如其来如-无所容也。-​" tabindex="-1">《象》曰：“突如其来如”，无所容也。 ​ <a class="header-anchor" href="#《象》曰-突如其来如-无所容也。-​" aria-label="Permalink to “《象》曰：“突如其来如”，无所容也。 ​”">​</a></h3><h2 id="六五-出涕沱若-戚嗟若-吉。-​" tabindex="-1">六五：出涕沱若，戚嗟若，吉。 ​ <a class="header-anchor" href="#六五-出涕沱若-戚嗟若-吉。-​" aria-label="Permalink to “六五：出涕沱若，戚嗟若，吉。 ​”">​</a></h2><p>王弼：履非其位，不胜所履。以柔乘刚，不能制下，下刚而进，将来害已，忧伤之深，至于沱嗟也。然所丽在尊，四为逆首，忧伤至深，众之所助，故乃沱嗟而获吉也。</p><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“出涕沱若”者，履非其位，不胜其任，以柔乘刚，不能制下，下刚而进，将来害已，忧伤之深，所以出涕滂沱，忧戚而咨嗟也。“若”是语辞也。“吉”者，以所居在尊位，四为逆首，已能忧伤悲嗟，众之所助，所以“吉”也。</p><h3 id="《象》曰-六五之-吉-离王公也。-​" tabindex="-1">《象》曰：六五之“吉”，离王公也。 ​ <a class="header-anchor" href="#《象》曰-六五之-吉-离王公也。-​" aria-label="Permalink to “《象》曰：六五之“吉”，离王公也。 ​”">​</a></h3><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：此释“六五吉”义也。所以终得吉者，以其所居在五，离附於王公之位，被众所助，故得吉也。五为王位，而言公者，此连王而言公，取其便文以会韵也。</p><h2 id="上九-王用出征-有嘉折首-获匪其丑-无咎。-​" tabindex="-1">上九：王用出征，有嘉折首，获匪其丑，无咎。 ​ <a class="header-anchor" href="#上九-王用出征-有嘉折首-获匪其丑-无咎。-​" aria-label="Permalink to “上九：王用出征，有嘉折首，获匪其丑，无咎。 ​”">​</a></h2><p>王弼：“离”，丽也，各得安其所丽谓之“离”。处离之极，离道已成，则除其非类以去民害，“王用出征”之时也。故必“有嘉折首，获匪其丑”，乃得“无咎”也。</p><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“王用出征”者，处离之极，离道既成，物皆亲附，当除去其非类，以去民害，故“王用出征”也。“有嘉折首，获匪其丑”者，以出征罪人，事必克获，故有嘉美之功，折断罪人之首，获得匪其丑类，乃得“无咎”也。若不出征除害，居在终极之地，则有咎也。</p><h3 id="《象》曰-王用出征-以正邦也。-​" tabindex="-1">《象》曰：“王用出征”，以正邦也。 ​ <a class="header-anchor" href="#《象》曰-王用出征-以正邦也。-​" aria-label="Permalink to “《象》曰：“王用出征”，以正邦也。 ​”">​</a></h3><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：释“出征”之义。言所出征者，除去民害，以正邦国故也。</p>',58)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
